# SECURE: check that THIS agent is allowed THIS tool
def invoke_tool(agent_token, tool_name, params):
    claims = verify_token(agent_token)
    if not claims:
        raise PermissionError("invalid token")
    if tool_name not in claims["allowed_tools"]:   # per-agent scoping
        raise PermissionError("agent not authorized for this tool")
    return TOOLS[tool_name](**params)
